//! Every case in `vectors/sframe`. `rfc9605.json` is RFC 9605 Appendix C; the
//! rest are generated by the Swift implementation. A unit test rather than an
//! integration test because the RFC's intermediate values (key, salt, nonce)
//! are not public API.

use std::path::PathBuf;

use aws_lc_rs::hmac;
use serde_json::Value;

use crate::key::label;
use crate::{
    CipherSuite, Context, Error, Header, Key, Metadata, Property, Receiver, epoch_tag, mls_key_id,
};

fn cases(name: &str) -> Vec<Value> {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../vectors/sframe")
        .join(name);
    let file: Value = serde_json::from_slice(&std::fs::read(&path).unwrap()).unwrap();
    assert_eq!(file["library"], "moqom-sframe", "{name}");
    let cases = file["cases"].as_array().unwrap().clone();
    assert!(!cases.is_empty(), "{name}");
    cases
}

fn hex(value: &Value) -> Vec<u8> {
    let s = value.as_str().unwrap();
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
        .collect()
}

fn to_hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

fn u64_of(value: &Value) -> u64 {
    value.as_u64().unwrap()
}

fn suite(case: &Value) -> CipherSuite {
    CipherSuite::try_from(u16::try_from(u64_of(&case["cipher_suite"])).unwrap()).unwrap()
}

fn metadata(value: &Value) -> Metadata {
    Metadata {
        group: u64_of(&value["group"]),
        object: u64_of(&value["object"]),
        priority: u8::try_from(u64_of(&value["priority"])).unwrap(),
        properties: value["properties"]
            .as_array()
            .unwrap()
            .iter()
            .map(|p| match p.get("integer") {
                Some(integer) => Property::integer(u64_of(&p["type"]), u64_of(integer)),
                None => Property::bytes(u64_of(&p["type"]), hex(&p["bytes_hex"])),
            })
            .collect(),
    }
}

fn check(name: &str, result: Result<Vec<u8>, Error>, case: &Value) {
    match (result, case.get("error")) {
        (Ok(plaintext), None) => assert_eq!(
            to_hex(&plaintext),
            case["pt_hex"].as_str().unwrap(),
            "{name}"
        ),
        (Err(error), Some(class)) => assert_eq!(error.class(), class.as_str().unwrap(), "{name}"),
        (result, expected) => panic!("{name}: got {result:?}, expected {expected:?}"),
    }
}

#[test]
fn rfc9605() {
    let (mut headers, mut sframes, mut skipped) = (0, 0, 0);
    for case in cases("rfc9605.json") {
        let name = case["name"].as_str().unwrap();
        if case.get("skip").is_some() {
            skipped += 1;
            continue;
        }
        match case["kind"].as_str().unwrap() {
            "header" => {
                headers += 1;
                let header = Header {
                    key_id: u64_of(&case["kid"]),
                    counter: u64_of(&case["ctr"]),
                };
                assert_eq!(
                    to_hex(&header.encode()),
                    case["header_hex"].as_str().unwrap(),
                    "{name}"
                );
                let encoded = hex(&case["header_hex"]);
                assert_eq!(
                    Header::read(&encoded).unwrap(),
                    (header, encoded.len()),
                    "{name}"
                );
            }
            "sframe" => {
                sframes += 1;
                let suite = suite(&case);
                let (kid, ctr) = (u64_of(&case["kid"]), u64_of(&case["ctr"]));
                let base = hex(&case["base_key_hex"]);
                assert_eq!(
                    label("SFrame 1.0 Secret key ", kid, suite),
                    hex(&case["sframe_key_label_hex"])
                );
                assert_eq!(
                    label("SFrame 1.0 Secret salt ", kid, suite),
                    hex(&case["sframe_salt_label_hex"])
                );
                // HKDF-Extract with an empty salt is HMAC under an empty key; the
                // PRK itself is opaque in aws-lc-rs.
                let algorithm = match suite {
                    CipherSuite::Aes128GcmSha256 => hmac::HMAC_SHA256,
                    CipherSuite::Aes256GcmSha512 => hmac::HMAC_SHA512,
                };
                let secret = hmac::sign(&hmac::Key::new(algorithm, &[]), &base);
                assert_eq!(
                    to_hex(secret.as_ref()),
                    case["sframe_secret_hex"].as_str().unwrap(),
                    "{name}"
                );
                let key = Key::new(kid, &base, suite);
                assert_eq!(
                    to_hex(&key.raw),
                    case["sframe_key_hex"].as_str().unwrap(),
                    "{name}"
                );
                assert_eq!(
                    to_hex(key.salt()),
                    case["sframe_salt_hex"].as_str().unwrap(),
                    "{name}"
                );
                assert_eq!(
                    to_hex(&key.nonce(ctr)),
                    case["nonce_hex"].as_str().unwrap(),
                    "{name}"
                );

                let mut aad = Header {
                    key_id: kid,
                    counter: ctr,
                }
                .encode();
                let header = aad.clone();
                aad.extend(hex(&case["metadata_hex"]));
                assert_eq!(aad, hex(&case["aad_hex"]), "{name}");
                let mut ct = header;
                ct.extend(key.seal(&hex(&case["pt_hex"]), ctr, &aad).unwrap());
                assert_eq!(to_hex(&ct), case["ct_hex"].as_str().unwrap(), "{name}");

                let receiver = Receiver::default();
                receiver.add(key);
                check(
                    name,
                    receiver.unprotect(&hex(&case["ct_hex"]), &hex(&case["metadata_hex"])),
                    &case,
                );
            }
            kind => panic!("{name}: unexpected kind {kind}"),
        }
    }
    assert_eq!((headers, sframes, skipped), (289, 2, 6));
}

#[test]
fn metadata_vectors() {
    for case in cases("metadata.json") {
        let name = case["name"].as_str().unwrap();
        match (metadata(&case["metadata"]).encode(), case.get("error")) {
            (Ok(bytes), None) => assert_eq!(
                to_hex(&bytes),
                case["encoded_hex"].as_str().unwrap(),
                "{name}"
            ),
            (Err(error), Some(class)) => {
                assert_eq!(error.class(), class.as_str().unwrap(), "{name}")
            }
            (result, expected) => panic!("{name}: got {result:?}, expected {expected:?}"),
        }
    }
}

#[test]
fn kid_vectors() {
    for case in cases("kid.json") {
        let name = case["name"].as_str().unwrap();
        let kid = u64_of(&case["kid"]);
        let leaf = u32::try_from(u64_of(&case["leaf"])).unwrap();
        assert_eq!(mls_key_id(leaf, u64_of(&case["epoch"])), kid, "{name}");
        assert_eq!(epoch_tag(kid), u64_of(&case["epoch_tag"]), "{name}");
        assert_eq!(
            to_hex(
                &Header {
                    key_id: kid,
                    counter: 0
                }
                .encode()
            ),
            case["header_hex"].as_str().unwrap()
        );
    }
}

#[test]
fn nonce_vectors() {
    for case in cases("nonce.json") {
        let name = case["name"].as_str().unwrap();
        let (kid, ctr) = (u64_of(&case["kid"]), u64_of(&case["ctr"]));
        let key = Key::new(kid, &hex(&case["base_key_hex"]), suite(&case));
        assert_eq!(
            to_hex(&key.raw),
            case["sframe_key_hex"].as_str().unwrap(),
            "{name}"
        );
        assert_eq!(
            to_hex(key.salt()),
            case["sframe_salt_hex"].as_str().unwrap(),
            "{name}"
        );
        assert_eq!(
            to_hex(&key.nonce(ctr)),
            case["nonce_hex"].as_str().unwrap(),
            "{name}"
        );
        assert_eq!(
            to_hex(
                &Header {
                    key_id: kid,
                    counter: ctr
                }
                .encode()
            ),
            case["header_hex"].as_str().unwrap()
        );
    }
}

#[test]
fn seal_open_vectors() {
    for case in cases("seal-open.json") {
        let name = case["name"].as_str().unwrap();
        let base = hex(&case["base_key_hex"]);
        let kid = u64_of(&case["kid"]);
        let sealer = Context::new(suite(&case), kid, &base);
        let opener = Context::new(suite(&case), kid, &base);
        let metadata = metadata(&case["metadata"]);
        for seal in case["seals"].as_array().unwrap() {
            let object = sealer.seal(&hex(&seal["pt_hex"]), &metadata).unwrap();
            assert_eq!(
                to_hex(&object),
                seal["object_hex"].as_str().unwrap(),
                "{name}"
            );
            check(
                name,
                opener.open(&hex(&seal["object_hex"]), &metadata),
                seal,
            );
        }
    }
}

#[test]
fn open_vectors() {
    for case in cases("open.json") {
        let name = case["name"].as_str().unwrap();
        let context = Context::new(
            suite(&case),
            u64_of(&case["kid"]),
            &hex(&case["base_key_hex"]),
        );
        check(
            name,
            context.open(&hex(&case["object_hex"]), &metadata(&case["metadata"])),
            &case,
        );
    }
}

#[test]
fn replay_vectors() {
    for case in cases("replay.json") {
        let name = case["name"].as_str().unwrap();
        let context = Context::with_replay_window(
            suite(&case),
            u64_of(&case["kid"]),
            &hex(&case["base_key_hex"]),
            u64_of(&case["replay_window"]),
        );
        let metadata = metadata(&case["metadata"]);
        for (index, step) in case["steps"].as_array().unwrap().iter().enumerate() {
            check(
                &format!("{name} step {index}"),
                context.open(&hex(&step["object_hex"]), &metadata),
                step,
            );
        }
    }
}
